// Copies the real chat UI out of public/index.html into public/assets/ui/ so the Android assistant panel
// (public/assistant.html) looks and behaves exactly like the app: same colours, message bubbles, prompt
// bar, live-voice orb, quiz/flashcard pop-up and icons. index.html stays the single source of truth;
// run `npm run build` (or `node scripts/build-shared-ui.js`) after changing those parts of it.
// `test/site.test.js` fails if the generated files are out of date.

const fs = require('fs');
const path = require('path');

const root = path.join(__dirname, '..');
const outDir = path.join(root, 'public', 'assets', 'ui');

// [first line starts with, stop before the line that starts with]
const CSS_BLOCKS = [
    ['        :root {', '        * { margin: 0; padding: 0; box-sizing: border-box;'],
    ['        * { margin: 0; padding: 0; box-sizing: border-box;', '        body {'],
    ['        .btn-ui {', '        #chat-box {'],
    ['        .msg {', '        /* ─── MINI-CODE-BOXZ'],
    ['        .typing {', '        /* ─── PROMPT AURA'],
    ['        /* ─── PROMPT AURA', '        /* ─── LOFI PLAYER'],
    ['        /* ─── LIVE VOICE MODE', '        /* ─── MINI PLAYER'],
    ['        /* ─── STUDY POP-UP', '        /* ─── LIMIT REACHED']
];
const JS_BLOCK = ['    // ─── STUDY TOOLS: quiz + flashcard pop-up', '    // A quiet heads-up (in the tips bar)'];

function slice(lines, [from, to], label) {
    const a = lines.findIndex((l) => l.startsWith(from));
    if (a < 0) throw new Error(`build-shared-ui: start marker not found for ${label}: ${from.trim()}`);
    const b = lines.findIndex((l, i) => i > a && l.startsWith(to));
    if (b < 0) throw new Error(`build-shared-ui: end marker not found for ${label}: ${to.trim()}`);
    return lines.slice(a, b).join('\n');
}

function build() {
    const html = fs.readFileSync(path.join(root, 'public', 'index.html'), 'utf8');
    const lines = html.split('\n');
    const header = '/* GENERATED by scripts/build-shared-ui.js from public/index.html. Do not edit by hand. */\n';

    // the stylesheet now lives in /assets/ui/, so page-relative image paths must become absolute
    const css = header + CSS_BLOCKS.map((b, i) => slice(lines, b, `css block ${i + 1}`)).join('\n\n').replace(/url\((['"]?)assets\//g, 'url($1/assets/') + '\n';

    const sprite = (html.match(/<svg style="display:none" aria-hidden="true">[\s\S]*?<\/svg>/) || [])[0];
    if (!sprite) throw new Error('build-shared-ui: icon sprite not found');
    const study = slice(lines, JS_BLOCK, 'study js');
    const js = header.trimEnd() + '\n'
        + '(function () {\n'
        + `    const sprite = ${JSON.stringify(sprite)};\n`
        + '    const mount = () => document.body.insertAdjacentHTML("afterbegin", sprite);\n'
        + '    if (document.body) mount(); else document.addEventListener("DOMContentLoaded", mount);\n'
        + '})();\n\n'
        + '// ── quiz + flashcard pop-up (needs escapeHtml, haptic and showAlert from the host page) ──\n'
        + study + '\n';

    return { 'app-ui.css': css, 'app-ui.js': js };
}

if (require.main === module) {
    fs.mkdirSync(outDir, { recursive: true });
    const files = build();
    for (const [name, text] of Object.entries(files)) {
        fs.writeFileSync(path.join(outDir, name), text);
        console.log(`Generated assets/ui/${name} (${text.length} bytes)`);
    }
}

module.exports = { build, outDir };
